const decisionTabs=[...document.querySelectorAll('.comparison-tabs [role="tab"]')];
function activateDecision(tab,focus=false){for(const item of decisionTabs){const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;document.getElementById(item.getAttribute('aria-controls')).hidden=!active;}if(focus)tab.focus();}
decisionTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activateDecision(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%decisionTabs.length;if(event.key==='ArrowLeft')next=(index+decisionTabs.length-1)%decisionTabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=decisionTabs.length-1;if(next!==undefined){event.preventDefault();activateDecision(decisionTabs[next],true);}});});

function setPhoto(wrapper,sceneRequested){const front=wrapper.querySelector('.product-front');const scene=wrapper.querySelector('.product-scene');const toggle=wrapper.querySelector('.view-toggle');wrapper.dataset.requested=sceneRequested?'scene':'product';const apply=()=>{const show=wrapper.dataset.requested==='scene'&&scene.complete&&scene.naturalWidth>0;wrapper.dataset.view=show?'scene':'product';front.setAttribute('aria-hidden',String(show));scene.setAttribute('aria-hidden',String(!show));toggle.setAttribute('aria-pressed',String(show));toggle.querySelector('.view-label').textContent=show?'Product view':'In context';toggle.setAttribute('aria-label',`${show?'Show product image':'Show second image'} of ${wrapper.closest('.product').querySelector('h3').textContent}`);wrapper.dataset.loading='false';};if(sceneRequested&&!scene.complete){wrapper.dataset.loading='true';scene.addEventListener('load',apply,{once:true});scene.addEventListener('error',()=>{wrapper.dataset.requested='product';apply();},{once:true});}else apply();}
document.querySelectorAll('.product-image').forEach(wrapper=>{const button=wrapper.querySelector('.view-toggle');wrapper.dataset.pinned='false';button.addEventListener('click',()=>{wrapper.dataset.pinned='true';setPhoto(wrapper,wrapper.dataset.view!=='scene');});wrapper.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'&&wrapper.dataset.pinned!=='true')setPhoto(wrapper,true);});wrapper.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'&&wrapper.dataset.pinned!=='true')setPhoto(wrapper,false);});});

const imageDialog=document.querySelector('.image-dialog');const largeImage=document.querySelector('#large-product-image');const imageCaption=document.querySelector('#image-dialog-caption');const originalLink=document.querySelector('#image-original');const imageStage=document.querySelector('.image-dialog-stage');
document.querySelectorAll('[data-image-zoom]').forEach(anchor=>anchor.addEventListener('click',event=>{if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();const wrapper=anchor.closest('.product-image');const scene=wrapper?.dataset.view==='scene';const source=wrapper?(scene?wrapper.dataset.sceneFull:wrapper.dataset.baseFull):anchor.href;const caption=anchor.dataset.caption+(wrapper?(scene?' · Context view':' · Product view'):'');imageStage.dataset.error='false';largeImage.alt=caption;largeImage.src=source;imageCaption.textContent=caption;originalLink.href=source;imageDialog.showModal();}));
largeImage.addEventListener('error',()=>{imageStage.dataset.error='true';});
document.querySelector('.image-close').addEventListener('click',()=>imageDialog.close());imageDialog.addEventListener('close',()=>{largeImage.removeAttribute('src');});imageDialog.addEventListener('click',event=>{if(event.target!==imageDialog)return;const rect=imageDialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)imageDialog.close();});
document.querySelectorAll('a[href^="#source-"]').forEach(anchor=>anchor.addEventListener('click',()=>{const target=document.getElementById(anchor.hash.slice(1));const details=target?.closest('details');if(details)details.open=true;}));
